CREATE POLICY "Leads restricted to internal readers" ON public.members_data AS RESTRICTIVE FOR SELECT TO authenticated USING (member_type <> 'lead' OR public.has_role(auth.uid(), 'admin'::public.app_role) OR public.is_board_member(auth.uid()) OR public.has_role(auth.uid(), 'inhuur'::public.app_role));
CREATE POLICY "Lead edits restricted to internal readers" ON public.member_edits AS RESTRICTIVE FOR SELECT TO authenticated USING (NOT EXISTS (SELECT 1 FROM public.members_data m WHERE m.id = member_edits.member_id AND m.member_type = 'lead') AND EXISTS (SELECT 1 FROM public.members_data m WHERE m.id = member_edits.member_id) OR public.has_role(auth.uid(), 'admin'::public.app_role) OR public.is_board_member(auth.uid()) OR public.has_role(auth.uid(), 'inhuur'::public.app_role));
CREATE POLICY "Lead conversions restricted to internal readers" ON public.lead_conversions AS RESTRICTIVE FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'::public.app_role) OR public.is_board_member(auth.uid()) OR public.has_role(auth.uid(), 'inhuur'::public.app_role));